deployment {
  Prod = Node_Environment 'Production' {

    Dmz = Zone_Vlan 'DMZ' {
      ProdApigwVm = Node_Vm 'prod-apigw-vm' {
        technology 'Kong'
        apiApp = Node_App 'API Gateway' {
          instanceOf platform.apiGateway
        }
      }
    }

    App = Zone_Vlan 'Application Tier' {
      ProdUploadVm = Node_Vm 'prod-upload-vm' {
        technology 'Node.js'
        uploadApp = Node_App 'Upload Service' {
          instanceOf platform.uploadService
        }
      }
      ProdWorkerVm = Node_Vm 'prod-worker-vm' {
        technology 'Go'
        workerApp = Node_App 'Processing Worker' {
          instanceOf platform.worker
        }
      }
    }

    Data = Zone_Vlan 'Data Tier' {
      ProdDbVm = Node_Vm 'prod-db-vm' {
        technology 'MongoDB'
        dbApp = Node_App 'MongoDB' {
          instanceOf platform.database
        }
      }
    }
  }
}

model {
  platform = system 'Document Platform' {
    apiGateway = Container_Api 'API Gateway' { ... }
    uploadService = Container_Service 'Upload Service' { ... }
  }
}

deployment {
  Prod = Node_Environment 'Production' {
    Dmz = Zone_Vlan 'DMZ' {
      // API Gateway, Web Server
    }
    AppTier = Zone_Vlan 'Application Tier' {
      // Microservices: Upload, Retrieval
    }
    ProcTier = Zone_Vlan 'Processing Tier' {
      // Message Queue, Workers
    }
    DataTier = Zone_Vlan 'Data Tier' {
      // Database, Object Storage
    }
  }
}

// DMZ to AppTier
Prod.Dmz.ApiVm -[https]-> Prod.AppTier.UploadVm 'Route upload requests'

// AppTier to ProcTier (async message publishing)
Prod.AppTier.UploadVm -[amqp]-> Prod.ProcTier.QueueVm 'Enqueue job'

// AppTier to DataTier
Prod.AppTier.UploadVm -[tcp]-> Prod.DataTier.DbVm 'Query metadata'

// ProcTier to DataTier
Prod.ProcTier.WorkerVm -[tcp]-> Prod.DataTier.DbVm 'Write results'

